// Organization settings (profile, subscription, billing, security), the invoice list, and the tax invoice / receipt documents.
// Everything is stored by the server (encrypted per organization); a save sends the whole section and the screen shows what
// the server kept. Invoices and receipts are generated by the server, never built in the browser.
export const name = 'settings';

const money = (n) => Number(n) || 0;

export async function load(logic, srv) {
  srv.etrDocs = srv.etrDocs || new Map();
  srv.etrAsked = srv.etrAsked || new Set();
  const all = await srv.request('GET', '/settings');
  apply(logic, all);
  srv.maxVideoMB = Number(all.security && all.security.maxVideoMB) || 50;
  srv.emailDetails = !(all.security && all.security.emailDetails === false);
  srv.commFiles = { maxMB: Number(all.security && all.security.maxFileMB) || 10, types: String((all.security && all.security.fileTypes) || '').toLowerCase().split(/[\s,]+/).filter(Boolean) };
  srv.plans = all.plans; srv.addons = all.addons; srv.seatsInUse = all.seats_in_use;
  try {
    const { invoices } = await srv.request('GET', '/billing/invoices');
    logic.setState({ invoices: invoices.map((i) => ({ no: i.no, date: i.date, amount: money(i.amount), status: i.status })) });
  } catch (e) { logic.setState({ invoices: [] }); }   // no right to see billing
}

function apply(logic, all) {
  logic.setState((st) => ({
    orgDeleteAfter: all.delete_after || '',
    orgProfile: { ...st.orgProfile, ...all.profile },
    orgSecurity: { ...st.orgSecurity, ...all.security },
    orgSub: { ...st.orgSub, ...all.subscription, addons: { storage: false, video: false, sms: false, ...(all.subscription.addons || {}) } },
    orgBilling: { ...st.orgBilling, ...all.billing }
  }));
}

export async function saveProfile(logic, srv, profile) {
  await srv.request('PUT', '/settings/profile', profile);
  await load(logic, srv);
}
export async function saveSecurity(logic, srv, security) {
  await srv.request('PUT', '/settings/security', security);
  srv.maxVideoMB = Number(security.maxVideoMB) || 50;
  srv.emailDetails = security.emailDetails !== false;
  await load(logic, srv);
}
// Starts the 30-day wait before the organization and all its data are erased.
export async function requestDeletion(logic, srv, name) {
  await srv.request('POST', '/settings/deletion', { confirm: name });
  await load(logic, srv);
}
export async function cancelDeletion(logic, srv) {
  await srv.request('DELETE', '/settings/deletion');
  await load(logic, srv);
}
export async function saveBilling(logic, srv, billing) {
  await srv.request('PUT', '/settings/billing', billing);
  await load(logic, srv);
}
// sub = the whole subscription as it should be; the server checks the plan's seat limit and the people already in.
export async function saveSubscription(logic, srv, sub) {
  const all = await srv.request('PUT', '/settings/subscription', { plan: sub.plan, cycle: sub.cycle, seats: sub.seats, autoRenew: !!sub.autoRenew, renews: sub.renews || '', status: sub.status || '', cancelAt: sub.cancelAt || '', addons: sub.addons || {} });
  apply(logic, all);
  srv.seatsInUse = all.seats_in_use;
}

// The server's tax invoice / receipt for one invoice, in the shape the document view prints. Fetched once per invoice.
export function ensureDoc(logic, srv, no) {
  if (srv.etrDocs.has(no) || srv.etrAsked.has(no)) return srv.etrDocs.get(no) || null;
  srv.etrAsked.add(no);
  srv.request('GET', `/billing/invoices/${encodeURIComponent(no)}/etr`).then((d) => { srv.etrDocs.set(no, fromServer(d)); logic.forceUpdate(); })
    .catch(() => { srv.etrAsked.delete(no); });
  return null;
}

function fromServer(d) {
  const f = d.fiscal || {};
  const s = d.seller || {};
  const b = d.buyer || {};
  return {
    invoiceNo: d.invoice_no, date: d.date, paid: d.status === 'Paid', status: d.status,
    seller: { name: s.Name, pin: s.PIN, vat: s.VAT, address: s.Address, phone: s.Phone, email: s.Email, web: '' },
    buyer: { name: b.name, pin: d.buyer_vat || b.taxId || 'Not provided', address: [b.address, b.city, b.country].filter(Boolean).join(', ') || '—', email: b.email || '—', phone: b.phone || '' },
    lines: (d.lines || []).map((l) => ({ desc: l.desc, qty: l.qty, net: l.net, vat: l.vat, gross: l.gross })),
    totals: { net: round2(d.net), vat: round2(d.vat), gross: Math.round(d.gross) },
    fiscal: { cuSerial: f.cu_serial, cuInvoice: f.cu_invoice, signature: f.signature, verifyUrl: '', integrated: !!f.integrated, note: f.note || '' },
    servedBy: 'Hub Billing'
  };
}
const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
